 const pair=(name,x,y,unit='puntos',method='Compara los valores de los dos periodos indicados; no mezcles el indicador con el precio.')=>record('Compara '+name,`Entre los periodos ${from+1} y ${to+1}, ¿qué ocurre con ${name}?`,method,`${name} ${direction(y-x)} en ${num(Math.abs(y-x))} ${unit}.`,`${name} ${direction(x-y)||'cambia'} en ${num(Math.abs(y-x)+1)} ${unit}.`,`${num(y)} − ${num(x)} = ${num(y-x)} ${unit}.`);
