  if(j===2||j===3){const diff=m[last]-g[last],prior=m[last-1]-g[last-1];return record('Lee el signo de la diferencia','¿Cómo cambia la separación con signo MACD menos señal entre los dos últimos periodos?','Resta señal a MACD en cada periodo. Compara las diferencias, no el precio de la acción.',`La diferencia ${direction(diff-prior)}.`,`La diferencia ${direction(prior-diff)}${diff===prior?' necesariamente':' '}.`,`Antes ${num(prior)} €; ahora ${num(diff)} €.`);}
  if(j===4){const crossings=[];for(let i=from+1;i<=to;i++)if(m[i-1]<=g[i-1]&&m[i]>g[i])crossings.push(i+1);return record('Distingue cruce y permanencia',`Entre las transiciones de los periodos ${from+1}–${to+1}, ¿cuántos cruces nuevos de MACD desde debajo o igual a encima de señal aparecen?`,'Un cruce necesita cambiar el orden: antes MACD≤señal y después MACD>señal.',`Hay ${crossings.length} cruces nuevos.`,`Hay ${(crossings.length+1)%3} cruces nuevos.`,`Los cruces aparecen en ${crossings.length?'los periodos '+crossings.join(', '):'ninguna de esas transiciones'}. Estar ya por encima no cuenta otra vez.`);}
  if(j===6)return pair('histograma MACD',h[from],h[to],'€');
